def symbols(el):
    """Map words of operators to symbols of operators.

    Arguments:
        el {str} -- word of operator

    Returns:
        str -- symbol of operator
    """
    el_lower = el.lower()
    if el_lower == "and":
        return "&"
    elif el_lower == "or":
        return "|"
    elif el_lower == "xor":
        return "^"
    elif el_lower == "possible":
        return "<>"
    elif el_lower == "necessary":
        return "[]"
    elif el_lower == "not":
        return "~"
    elif el_lower == "if":
        return "->"
    elif el_lower == "iff":
        return "<->"
    else:
        return el

